def min_cuts_for_beautiful_binary(s: str) -> int:
    n = len(s)
    # Precompute all binary representations of powers of 5 up to length n
    powers = set()
    k = 0
    while True:
        bin_str = bin(5**k)[2:]
        if len(bin_str) > n:
            break
        powers.add(bin_str)
        k += 1

    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            if s[j:i] in powers:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n] - 1 if dp[n] != float('inf') else -1
```

