def can_split_to_n(nums, n, m):
    """
    Check if the array nums can be split into exactly n subarrays, where
    a split is allowed only if each resulting part is either length 1 or has sum >= m.
    """
    if n > len(nums):
        return False
    if n == len(nums):
        return True  # each element can be its own array (length 1)

    # dp[i][k] = True if we can split prefix nums[:i] into k valid subarrays
    dp = [[False] * (n + 1) for _ in range(len(nums) + 1)]
    dp[0][0] = True

    for i in range(1, len(nums) + 1):
        for k in range(1, n + 1):
            # Option 1: last subarray is a single element
            if dp[i-1][k-1]:
                dp[i][k] = True
                continue

            # Option 2: last subarray has length >= 2 and sum >= m
            total = 0
            for j in range(i-1, -1, -1):
                total += nums[j]
                if total >= m and dp[j][k-1]:
                    dp[i][k] = True
                    break

    return dp[len(nums)][n]
```

