                if current_sum >= m:
                    if start == 0 and k == 1:
                        dp[i][k] = True
                    elif start > 0 and dp[start][k-1]:
                        dp[i][k] = True
                        break
                # If we've added too many elements for remaining parts, stop
                if k == 1 and start == 0:
                    break

    return dp[n][target]
