def can_split_into_n(nums, m, target):
    n = len(nums)
    # dp[i][k] = True if first i elements can be split into k valid parts
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for k in range(1, min(i, target) + 1):
            # Option 1: single element part at position i-1
            if dp[i-1][k-1]:
                dp[i][k] = True
                continue

            # Option 2: part with sum >= m, ending at position i-1
            current_sum = 0
            for start in range(i-1, -1, -1):
                current_sum += nums[start]
                if current_sum >= m:
                    if start == 0 and k == 1:
                        dp[i][k] = True
                    elif start > 0 and dp[start][k-1]:
                        dp[i][k] = True
                        break
                # If we've added too many elements for remaining parts, stop
                if k == 1 and start == 0:
                    break

    return dp[n][target]
